public class DOMNodePointer_findEnclosingAttribute_TriageGen1Test {

    /**
     * Helper method to invoke the protected static method via reflection.
     */
    private String invokeFindEnclosingAttribute(Node n, String attrName) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("findEnclosingAttribute", Node.class, String.class);
        method.setAccessible(true);
        return (String) method.invoke(null, n, attrName);
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        assertNull(invokeFindEnclosingAttribute(null, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnCurrentNode() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("target")).thenReturn("value1");

        assertEquals("value1", invokeFindEnclosingAttribute(element, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnParentNode() throws Exception {
        Element parent = mock(Element.class);
        Element child = mock(Element.class);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("parentValue");
        when(parent.getParentNode()).thenReturn(null);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn(""); // Empty string should be ignored
        when(child.getParentNode()).thenReturn(parent);

        assertEquals("parentValue", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnGrandparent() throws Exception {
        Element grandparent = mock(Element.class);
        Element parent = mock(Element.class);
        Element child = mock(Element.class);

        when(grandparent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(grandparent.getAttribute("target")).thenReturn("grandparentValue");
        when(grandparent.getParentNode()).thenReturn(null);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn(null); // Null should be ignored
        when(parent.getParentNode()).thenReturn(grandparent);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn(""); 
        when(child.getParentNode()).thenReturn(parent);

        assertEquals("grandparentValue", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NonElementNodeTraversed() throws Exception {
        Element parent = mock(Element.class);
        Node textNode = mock(Node.class);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("found");
        when(parent.getParentNode()).thenReturn(null);

        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(parent);

        assertEquals("found", invokeFindEnclosingAttribute(textNode, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NoAttributeFoundInHierarchy() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("missing")).thenReturn("");
        when(element.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(element, "missing"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsAtRoot() throws Exception {
        Element root = mock(Element.class);
        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getAttribute("target")).thenReturn("rootValue");
        when(root.getParentNode()).thenReturn(null);

        assertEquals("rootValue", invokeFindEnclosingAttribute(root, "target"));
    }
}
